// High-density, offline 3MF importer for Android. No DOMParser and no
// unzipSync of a 200-500 MB model XML. ZIP and XML are consumed incrementally;
// 3D geometry stays in compact typed arrays. The previous ThreeMFLoader
// cannot safely parse the multi-million-face archives generated by this app.
import * as THREE from 'three';
import {Unzip,UnzipInflate} from 'fflate';

const FLOAT_LIMIT=16_000_000;
class Growing {
 constructor(Type,initial=65536){this.Type=Type;this.data=new Type(initial);this.used=0;}
 push(...values){
  const need=this.used+values.length;
  if(need>FLOAT_LIMIT*4)throw Error('3MF: слишком много данных для памяти Android');
  if(need>this.data.length){
   const next=new this.Type(Math.max(need,this.data.length*2));
   next.set(this.data);this.data=next;
  }
  this.data.set(values,this.used);this.used=need;
 }
 finish(){return this.data.slice(0,this.used)}
 get length(){return this.used}
}
const attr=(s,name)=>{
 const mark=' '+name+'="',begin=s.indexOf(mark);
 if(begin<0)return null;
 const start=begin+mark.length,end=s.indexOf('"',start);
 return end<0?null:s.slice(start,end);
};
const number=(s,name)=>{
 const value=Number(attr(s,name));
 if(!Number.isFinite(value))throw Error('3MF: некорректный '+name);
 return value;
};
const integer=(s,name)=>{
 const value=number(s,name);
 if(!Number.isSafeInteger(value)||value<0)throw Error('3MF: некорректный индекс '+name);
 return value;
};
const scaleOf=u=>({
 millimeter:.001,meter:1,centimeter:.01,micron:.000001,
 inch:.0254,foot:.3048
})[u]??.001;
const shortPath=s=>String(s||'').replaceAll('\\','/').replace(/^\/+/, '').toLowerCase();
const sleep=()=>new Promise(resolve=>setTimeout(resolve,0));

class ModelXML {
 constructor(){
  this.decoder=new TextDecoder();this.tail='';this.unit=.001;
  this.textureDefs=new Map();this.uvGroups=new Map();this.colors=new Map();
  this.currentUV=null;this.currentBase=null;this.objects=[];
  this.inVertices=false;this.inTriangles=false;this.modelStarted=false;
  this.currentObject=null;this.totalTriangles=0;
 }
 feed(chunk,last=false){
  const str=this.decoder.decode(chunk,{stream:!last});
  const source=this.tail+str;
  let at=0;
  for(;;){
   const begin=source.indexOf('<',at);
   if(begin<0){this.tail='';break}
   const end=source.indexOf('>',begin+1);
   if(end<0){this.tail=source.slice(begin);break}
   const tag=source.slice(begin,end+1);
   this.tag(tag);
   at=end+1;
  }
  if(last&&this.tail.trim())throw Error('3MF: XML не завершён');
 }
 tag(t){
  if(t.startsWith('<?')||t.startsWith('<!--'))return;
  if(t.startsWith('<model ')){this.modelStarted=true;this.unit=scaleOf(attr(t,'unit'));return}
  if(t.startsWith('<m:texture2d ')){
   this.textureDefs.set(integer(t,'id'),shortPath(attr(t,'path')));return;
  }
  if(t.startsWith('<m:texture2dgroup ')){
   const id=integer(t,'id');
   this.currentUV=new Growing(Float32Array);
   this.uvGroups.set(id,{texid:integer(t,'texid'),uv:this.currentUV});
   return;
  }
  if(t.startsWith('</m:texture2dgroup')){this.currentUV=null;return}
  if(t.startsWith('<m:tex2coord ')){
   if(this.currentUV)this.currentUV.push(number(t,'u'),number(t,'v'));
   return;
  }
  if(t.startsWith('<basematerials ')){
   this.currentBase=integer(t,'id');return;
  }
  if(t.startsWith('<base ')){
   if(this.currentBase!==null)
    this.colors.set(this.currentBase,attr(t,'displaycolor')||'#FFFFFFFF');
   return;
  }
  if(t.startsWith('</basematerials')){this.currentBase=null;return}
  if(t.startsWith('<object ')){
   this.currentObject={
    name:attr(t,'name')||'3MF Mesh',
    id:integer(t,'id'),
    positions:new Growing(Float32Array),indices:new Growing(Uint32Array),
    groups:[],faceGroup:null,faceStart:0,faces:0,
    uvByFace:null
   };
   return;
  }
  if(t.startsWith('<vertices')){this.inVertices=true;return}
  if(t.startsWith('</vertices')){this.inVertices=false;return}
  if(t.startsWith('<triangles')){this.inTriangles=true;return}
  if(t.startsWith('</triangles')){this.inTriangles=false;return}
  if(this.currentObject&&this.inVertices&&t.startsWith('<vertex ')){
   const unit=this.unit;
   // 3MF is Z-up; Three.js is Y-up. Convert to metres.
   this.currentObject.positions.push(
    number(t,'x')*unit,number(t,'z')*unit,-number(t,'y')*unit);
   return;
  }
  if(this.currentObject&&this.inTriangles&&t.startsWith('<triangle ')){
   const obj=this.currentObject;
   const a=integer(t,'v1'),b=integer(t,'v2'),c=integer(t,'v3');
   const pid=attr(t,'pid')!==null?integer(t,'pid'):0;
   const p1=attr(t,'p1'),p2=attr(t,'p2'),p3=attr(t,'p3');
   // The current Model Forge 3MF writer keeps vertex and UV indices
   // aligned. Never silently mis-map independent corner UVs.
   if(this.uvGroups.has(pid)&&p1!==null&&
     (Number(p1)!==a||Number(p2)!==b||Number(p3)!==c))
    throw Error('3MF: независимые UV-индексы требуют отдельного режима развёртки');
   if(obj.faceGroup!==pid){
    if(obj.faceGroup!==null)obj.groups.push({pid:obj.faceGroup,
     start:obj.faceStart,count:obj.faces*3-obj.faceStart});
    obj.faceGroup=pid;obj.faceStart=obj.faces*3;
   }
   obj.indices.push(a,b,c);obj.faces++;this.totalTriangles++;
   return;
  }
  if(t.startsWith('</object')){
   const obj=this.currentObject;
   if(obj){
    if(obj.faceGroup!==null)obj.groups.push({
     pid:obj.faceGroup,start:obj.faceStart,count:obj.faces*3-obj.faceStart
    });
    if(obj.faces)this.objects.push(obj);
   }
   this.currentObject=null;return;
  }
 }
 async scene(assets,{loadTextures=true}={}){
  if(!this.modelStarted||!this.objects.length)
   throw Error('3MF: файл не содержит читаемой 3D-сетки');
  const root=new THREE.Group();root.name='Imported_3MF';
  const textureCache=new Map();
  const makeTexture=async texid=>{
   if(textureCache.has(texid))return textureCache.get(texid);
   const file=this.textureDefs.get(texid);
   if(!file)throw Error('3MF: текстурный ресурс не указан');
   const source=assets.get(file);
   if(!source)throw Error('3MF: внутри архива нет PNG '+file);
   if(!loadTextures){textureCache.set(texid,null);return null}
   if(typeof document==='undefined'||typeof URL.createObjectURL!=='function'){
    textureCache.set(texid,null);return null;
   }
   const blob=new Blob([source],{type:'image/png'});
   const url=URL.createObjectURL(blob);
   try{
    const map=await new THREE.TextureLoader().loadAsync(url);
    map.flipY=false;map.colorSpace=THREE.SRGBColorSpace;map.needsUpdate=true;
    textureCache.set(texid,map);return map;
   }finally{URL.revokeObjectURL(url)}
  };
  for(const item of this.objects){
   const numVerts=item.positions.length/3;
   if(!numVerts||!item.indices.length)continue;
   const geometry=new THREE.BufferGeometry();
   geometry.setAttribute('position',new THREE.BufferAttribute(item.positions.finish(),3));
   geometry.setIndex(new THREE.BufferAttribute(item.indices.finish(),1));
   const ids=[...new Set(item.groups.map(g=>g.pid))];
   const materials=[];
   for(const id of ids){
    const uvGroup=this.uvGroups.get(id);
    let material;
    if(uvGroup){
     const uv=uvGroup.uv.finish();
     if(uv.length!==numVerts*2)
      throw Error('3MF: UV-координат не столько, сколько вершин — нельзя надёжно восстановить текстуру');
     if(!geometry.getAttribute('uv'))geometry.setAttribute('uv',
      new THREE.BufferAttribute(uv,2));
     const map=await makeTexture(uvGroup.texid);
     material=new THREE.MeshStandardMaterial({map,side:THREE.DoubleSide});
    }else{
     material=new THREE.MeshStandardMaterial({
      color:this.colors.get(id)?.slice(0,7)||'#ffffff',
      side:THREE.DoubleSide
     });
    }
    materials.push(material);
   }
   for(const group of item.groups){
    const slot=ids.indexOf(group.pid);
    geometry.addGroup(group.start,group.count,slot>=0?slot:0);
   }
   geometry.computeVertexNormals();
   const mesh=new THREE.Mesh(geometry,materials.length===1?materials[0]:materials);
   mesh.name=item.name;mesh.frustumCulled=false;root.add(mesh);
  }
  if(!root.children.length)throw Error('3MF: геометрия пустая');
  return root;
 }
}
export async function importStreaming3mf(data,{loadTextures=true,onProgress=null}={}){
 const input=data instanceof Uint8Array?data:new Uint8Array(data);
 if(input.length<22||input[0]!==0x50||input[1]!==0x4b)
  throw Error('3MF: отсутствует ZIP-заголовок');
 const model=new ModelXML(),assets=new Map();
 let failure=null,modelFinished=false;
 const unzipper=new Unzip(file=>{
  const name=shortPath(file.name);
  if(name.endsWith('.model')){
   file.ondata=(error,bytes,final)=>{
    if(error){failure=error;return}
    try{model.feed(bytes,final);if(final)modelFinished=true}
    catch(e){failure=e}
   };
   file.start();
  }else if(name.endsWith('.png')){
   const chunks=[];let length=0;
   file.ondata=(error,bytes,final)=>{
    if(error){failure=error;return}
    if(bytes.length){chunks.push(bytes);length+=bytes.length}
    if(final){
     const merged=new Uint8Array(length);let pos=0;
     for(const part of chunks){merged.set(part,pos);pos+=part.length}
     assets.set(name,merged);
    }
   };
   file.start();
  }else{
   // Skip unknown/non-model archive components.
   file.ondata=()=>{};
   file.start();
  }
 });
 unzipper.register(UnzipInflate);
 const STEP=256*1024;
 for(let offset=0;offset<input.length;offset+=STEP){
  const end=Math.min(input.length,offset+STEP);
  unzipper.push(input.subarray(offset,end),end===input.length);
  if(failure)throw failure;
  if((offset/STEP)%8===0){
   onProgress?.(Math.min(95,Math.round(end/input.length*95)));
   await sleep();
  }
 }
 if(failure)throw failure;
 if(!modelFinished)throw Error('3MF: распаковка XML не завершена');
 onProgress?.(97);
 const root=await model.scene(assets,{loadTextures});
 onProgress?.(100);
 return {root,clips:[],triangles:model.totalTriangles,
  textures:assets.size,
  notice:'3MF импортирован без ограничения числа треугольников. '+
   model.totalTriangles.toLocaleString('ru-RU')+
   ' треугольников; геометрия и встроенные PNG загружены потоково.'};
}
